sys_ui_context_menu.action_script:
var nsProTaskMain;

nsProTaskMain = parent.top.window.gsft_main;

assignPortToLocalCircuit();

function assignPortToLocalCircuit() {
    var formTitle = "Configure Proposed Port " + nsProTaskMain.g_form.getValue('name');
    var site = nsProTaskMain.g_form.getValue('x_g_sonc_ns_pro_site');
    //var localCircuitID = nsProTaskMain.g_form.getUniqueValue();
	alert(site);

    var gmf = new GlideModalForm(formTitle, 'x_g_sonc_ns_pro_port', formCompleted);
    gmf.addParm('sys_id', g_sysId);
	gmf.addParm("sysparm_view", "proposedports");
	gmf.addParm("sysparm_view_forced", true);
    //gmf.setOnloadCallback(populateDefaults);


    gmf.render();

    // function populateDefaults(modalForm) {
    //     var iframe = modalForm.$window.find("#dialog_frame")[0];
    //     var iframeWindow = iframe.contentWindow ? iframe.contentWindow : iframe.contentDocument.defaultView;
    //     var d_form = iframeWindow.g_form;
    //     d_form.setValue('site', site);
    //     d_form.setValue('local_circuit_id', localCircuitID);
	// 	//jQuery("#dialog_frame")[0].contentWindow.jQuery("#page_timing_div").hide();
	// 	//jQuery(".modal-content").css("width", "100%").css("margin", "0 auto");

    // }



}
    function formCompleted() {
        location.reload();
    }

sys_ui_context_menu.on_show_script:
canBeConfigured();

function canBeConfigured() {

    var proposed = false;
	related = g_list.getRelated();

    if (related == "REL:7036d84a472d1a5440fd43ff336d4325" ) {
        proposed = true;
    }
    if (proposed) {
        g_menu.setEnabled(g_item);
        g_menu.setLabel(g_item, "<b style='color:DodgerBlue;'>• Configure Proposed Port •</b>");

    } else {
        g_menu.setDisabled(g_item);
    }

}
